def topo_sort(graph):
    from collections import defaultdict, deque

    # Copy graph to avoid mutation
    graph = dict(graph)

    # Build reverse dependencies: node -> list of dependent nodes
    reverse_deps = defaultdict(list)
    all_nodes = set()
    for node, deps in graph.items():
        all_nodes.add(node)
        all_nodes.update(deps)
        for dep in deps:
            reverse_deps[dep].append(node)

    # Track prerequisites already added
    added = set()

    result = []

    for node in sorted(all_nodes):
        if node in added:
            continue
        # Check for cycles using DFS
        visited = {}
        def dfs(n, stack):
            visited[n] = 1  # visiting
            for dep in graph.get(n, []):
                if dep not in visited:
                    visited[dep] = 2  # done
                elif visited[dep] == 1:
                    raise ValueError("Cycle detected")
            visited[n] = 2  # done

        dfs(node, None)
        added.add(node)

    for node in sorted(all_nodes):
        if node in added:
            continue
        # Collect prerequisites
        prereqs = []
        for dep in sorted(set(graph.get(node, []))):
            if dep in added:
                prereqs.append(dep)
            else:
                # Recursively add prerequisites
                result.extend(topo_sort({dep: graph.get(dep, [])}))
                prereqs.append(dep)
        result.extend(sorted(prereqs))
        added.add(node)

    return result
