def window_sums(nums, k):
    if k <= 0:
        raise ValueError("k must be positive")
    if k > len(nums):
        return []
    result = []
    curr_sum = sum(nums[:k])
    result.append(curr_sum)
    for i in range(k, len(nums)):
        curr_sum = curr_sum - nums[i - k] + nums[i]
        result.append(curr_sum)
    return result

