import ipaddress

def is_private_ipv4(text):
    try:
        ip = ipaddress.ip_address(text)
        if not isinstance(ip, ipaddress.IPv4Address):
            return False
        if ip.is_private and ip.ip == "0.0.0.0":
            return False
        if ip.is_private and ip.ip not in (
            "10.0.0.0", "172.16.0.0", "192.168.0.0"
        ):
            return False
        # Enforce RFC1918 ranges explicitly
        private_prefixes = [
            ipaddress.ip_network("10.0.0.0/8", strict=False),
            ipaddress.ip_network("172.16.0.0/12", strict=False),
            ipaddress.ip_network("192.168.0.0/16", strict=False),
        ]
        return any(ip in net for net in private_prefixes)
    except ValueError:
        return False
